#!/usr/bin/env bash

# ---- Create ftdetect file for a language ----
_create_ftdetect() {
  local lang="$1"
  local ftdetect_file="${VIMX_ROOT}/ftdetect/${lang}.vim"

  if [ -f "$ftdetect_file" ]; then
    return 0
  fi

  cat > "$ftdetect_file" << EOF
" Filetype detection for ${lang}
" Generated by vimx lang add ${lang}

" Detect by file extension
autocmd BufRead,BufNewFile *.${lang} set filetype=${lang}

" Add more patterns as needed:
" autocmd BufRead,BufNewFile *.${lang}.* set filetype=${lang}
" autocmd BufRead,BufNewFile *.*.${lang} set filetype=${lang}
EOF
  echo "$ftdetect_file"
}

# ---- Create syntax file for a language ----
_create_syntax() {
  local lang="$1"
  local syntax_file="${VIMX_ROOT}/syntax/${lang}.vim"

  if [ -f "$syntax_file" ]; then
    return 0
  fi

  cat > "$syntax_file" << EOF
" Syntax highlighting for ${lang}
" Generated by vimx lang add ${lang}
"
" This is a minimal syntax file. For full syntax support,
" consider installing a plugin: vimx add <user>/vim-${lang}

if exists("b:current_syntax")
  finish
endif

" Keywords
syn keyword ${lang}Keyword if then else endif while do done for in function return
syn keyword ${lang}Keyword class struct enum interface typedef import export

" Comments
syn match ${lang}Comment "//.*$"
syn match ${lang}Comment "#.*$"
syn region ${lang}Comment start="/\*" end="\*/"

" Strings
syn region ${lang}String start='"' end='"' contains=Escape
syn region ${lang}String start="'" end="'" contains=Escape
syn region ${lang}String start='\`' end='\`' contains=Escape
syn match ${lang}Escape contained /\\./

" Numbers
syn match ${lang}Number "\<\d\+\>"
syn match ${lang}Number "\<0[xX][0-9a-fA-F]\+\>"
syn match ${lang}Number "\<0[oO][0-7]\+\>"
syn match ${lang}Number "\<0[bB][01]\+\>"

" Highlighting
hi def link ${lang}Keyword    Keyword
hi def link ${lang}Comment    Comment
hi def link ${lang}String     String
hi def link ${lang}Escape     Special
hi def link ${lang}Number     Number

let b:current_syntax = "${lang}"
EOF
  echo "$syntax_file"
}

add_language() {
  local lang="${1}"
  local lang_file="${VIMX_LANGS_DIR}/${lang}.vim"

  if grep -q "#define LANGUAGE" "$VIMX_INIT" && grep -q "#enddef LANGUAGE" "$VIMX_INIT"; then
    if grep -q "runtime! langs/$lang.vim" "$VIMX_INIT"; then
      print_warning "Configuration ${CYAN}$lang${NC} is already exists"
      return 0
    fi

    tmp_file=$(mktemp)
    awk -v lang="$lang" '
    /#enddef LANGUAGE/ && !added {
    print "runtime! " "langs/" lang ".vim"
    added=1
  }
{ print }
    ' "$VIMX_INIT" >"$tmp_file" && mv "$tmp_file" "$VIMX_INIT"

    if [ -f "$lang_file" ]; then
      print_warning "Added to configuration is successfully but language file: ${CYAN}$lang_file${NC} is already exists"
    else
      touch "$lang_file"
      print_success "Added new language ${CYAN}$lang_file${NC} is successfully"
    fi
  else
    cat >>"$VIMX_INIT" <<EOF
" Load language configurations
" Don't remove 'define LANGUAGE' and 'enddef LANGUAGE' from comment
" #define LANGUAGE
runtime! langs/${lang}.vim
" #enddef LANGUAGE
EOF
    # Buat file bahasa
    touch "$lang_file"
    print_success "Added new language ${CYAN}$lang${NC} with new section"
  fi

  # Create ftdetect file
  local ftdetect_file
  ftdetect_file=$(_create_ftdetect "$lang")
  if [ -n "$ftdetect_file" ]; then
    print_info "Created filetype detection: ${CYAN}${ftdetect_file}${NC}"
  fi

  # Create syntax file
  local syntax_file
  syntax_file=$(_create_syntax "$lang")
  if [ -n "$syntax_file" ]; then
    print_info "Created syntax highlighting: ${CYAN}${syntax_file}${NC}"
  fi
}

disable_language() {
  local lang="${1}"
  local lang_pattern="runtime! langs/${lang}.vim"

  if [[ ! -f "$VIMX_INIT" ]]; then
    print_error "Configuration file $VIMX_INIT not found"
    return 1
  fi

  if ! grep -q "$lang_pattern" "$VIMX_INIT"; then
    print_warning "Language ${CYAN}$lang${NC} not found"
    return 0
  fi

  if grep -q "$lang_pattern" "$VIMX_INIT" || grep -q "^[^\"].*$lang_pattern" "$VIMX_INIT"; then
    tmp_file=$(mktemp)
    awk -v pattern="$lang_pattern" '
      $0 ~ pattern && !/^"/ {
        $0 = "\" " $0
      }
      { print }
    ' "$VIMX_INIT" >"$tmp_file" && mv "$tmp_file" "$VIMX_INIT"

    print_success "Language ${CYAN}$lang${NC} disabled successfully"
  else
    print_warning "Language ${CYAN}$lang${NC} is already disabled"
  fi
}

enable_language() {
  local lang="${1}"

  if [[ ! -f "$VIMX_INIT" ]]; then
    print_error "Configuration file $VIMX_INIT not found"
    return 1
  fi

  if grep -q "^\" *runtime! langs/${lang}.vim" "$VIMX_INIT"; then
    tmp_file=$(mktemp)
    awk -v lang="$lang" '
      /^" *runtime! langs\/.*\.vim/ {
        if (index($0, "langs/" lang ".vim") > 0) {
          sub(/^" */, "")
        }
      }
      { print }
    ' "$VIMX_INIT" >"$tmp_file" && mv "$tmp_file" "$VIMX_INIT"

    print_success "Language ${CYAN}$lang${NC} enabled successfully"
  elif grep -q "^runtime! langs/${lang}.vim" "$VIMX_INIT"; then
    print_warning "Language ${CYAN}$lang${NC} is already enabled"
  else
    print_error "Language ${CYAN}$lang${NC} not found in configuration"
    return 1
  fi
}

info_language() {
  local lang="${1}"
  local lang_file="${VIMX_LANGS_DIR}/${lang}.vim"

  if [[ ! -f "$lang_file" ]]; then
    print_error "Language ${CYAN}$lang${NC} not found"
    return 1
  fi

  local status="Disabled"
  if grep -q "^runtime! langs/${lang}.vim" "$VIMX_INIT"; then
    status="${GREEN}Enabled${NC}"
  elif grep -q "^\" *runtime! langs/${lang}.vim" "$VIMX_INIT"; then
    status="${YELLOW}Disabled${NC}"
  else
    status="${RED}Not in config${NC}"
  fi

  local file_size=$(stat -f%z "$lang_file" 2>/dev/null || stat -c%s "$lang_file" 2>/dev/null)
  local line_count=$(wc -l <"$lang_file")
  local created_date=$(stat -f%SB "$lang_file" 2>/dev/null || stat -c%y "$lang_file" 2>/dev/null | cut -d' ' -f1)

  print_header "Language Information: ${CYAN}$lang${NC}"

  local info_data=(
    "Status|$(echo -e $status)"
    "File|$lang_file"
    "Size|$file_size bytes"
    "Lines|$line_count"
    "Created|$created_date"
  )

  for info in "${info_data[@]}"; do
    IFS='|' read -r label value <<<"$info"
    printf "  ${YELLOW}%-10s:${NC} %s\n" "$label" "$value"
  done

  # Show ftdetect and syntax status
  echo ""
  echo -e "  ${YELLOW}ftdetect:${NC} $([ -f "${VIMX_ROOT}/ftdetect/${lang}.vim" ] && echo "${GREEN}exists${NC}" || echo "${RED}missing${NC}")"
  echo -e "  ${YELLOW}syntax:${NC}   $([ -f "${VIMX_ROOT}/syntax/${lang}.vim" ] && echo "${GREEN}exists${NC}" || echo "${RED}missing${NC}")"

  echo ""
  print_header "File Preview"
  if [[ $line_count -gt 20 ]]; then
    echo -e "  ${GRAY}(Showing first 20 lines)${NC}"
    head -n 20 "$lang_file" | sed 's/^/  /'
    echo -e "  ${GRAY}... and $((line_count - 20)) more lines${NC}"
  else
    cat "$lang_file" | sed 's/^/  /'
  fi
}

list_language() {
  local languages=()
  while IFS= read -r f; do [ -n "$f" ] && languages+=("$f"); done < <(find "${VIMX_LANGS_DIR}" -name "*.vim" 2>/dev/null | sort)
  local current=0
  local table_data=()

  print_header "Supported Languages"
  echo ""

  if [ ${#languages[@]} -eq 0 ]; then
    print_warning "No language configurations found"
    return 1
  fi

  for lang in "${languages[@]}"; do
    current=$((current + 1))
    local lang_name
    lang_name=$(basename "$lang" .vim)
    local has_ftdetect=""
    local has_syntax=""
    [ -f "${VIMX_ROOT}/ftdetect/${lang_name}.vim" ] && has_ftdetect="✓" || has_ftdetect="✗"
    [ -f "${VIMX_ROOT}/syntax/${lang_name}.vim" ] && has_syntax="✓" || has_syntax="✗"
    table_data+=("$current|$lang_name|$has_ftdetect|$has_syntax")
  done

  create_simple_table "No,Language,ftdetect,syntax" "${table_data[@]}"
  echo ""
  echo -e "Edit: ${CYAN}vimx lang edit <name>${NC}"
  echo -e "Add:  ${CYAN}vimx lang add <name>${NC}"
}

remove_language() {
  local lang="${1}"
  local lang_file="${VIMX_LANGS_DIR}/${lang}.vim"
  local lang_pattern="runtime! langs/${lang}.vim"

  if [[ ! -f "$VIMX_INIT" ]]; then
    print_error "Configuration file $VIMX_INIT not found"
    return 1
  fi

  if grep -q "$lang_pattern" "$VIMX_INIT"; then
    tmp_file=$(mktemp)
    awk -v pattern="$lang_pattern" '
      $0 !~ pattern { print }
    ' "$VIMX_INIT" >"$tmp_file" && mv "$tmp_file" "$VIMX_INIT"

    print_success "Language ${CYAN}$lang${NC} removed from configuration"
  else
    print_warning "Language ${CYAN}$lang${NC} not found in configuration"
  fi

  if [[ -f "$lang_file" ]]; then
    local question=$(echo -e "Delete language file ${CYAN}${lang_file}${NC}? (y/N): ")
    read -p "$question" -n 1 -r
    echo
    if [[ $REPLY =~ ^[Yy]$ ]]; then
      rm -f "$lang_file"
      print_success "Language file ${CYAN}$lang_file${NC} deleted"
    else
      print_warning "Language file ${CYAN}$lang_file${NC} kept"
    fi
  fi

  # Offer to remove ftdetect and syntax files
  local ftdetect_file="${VIMX_ROOT}/ftdetect/${lang}.vim"
  local syntax_file="${VIMX_ROOT}/syntax/${lang}.vim"

  if [ -f "$ftdetect_file" ] || [ -f "$syntax_file" ]; then
    local question=$(echo -e "Delete ftdetect/syntax files for ${CYAN}${lang}${NC}? (y/N): ")
    read -p "$question" -n 1 -r
    echo
    if [[ $REPLY =~ ^[Yy]$ ]]; then
      [ -f "$ftdetect_file" ] && rm -f "$ftdetect_file" && print_success "Deleted ${CYAN}ftdetect/${lang}.vim${NC}"
      [ -f "$syntax_file" ] && rm -f "$syntax_file" && print_success "Deleted ${CYAN}syntax/${lang}.vim${NC}"
    fi
  fi
}

# ---- Scaffold a custom language with all files ----
scaffold_language() {
  local lang="${1}"
  [ -z "$lang" ] && { print_error "Usage: vimx lang scaffold <language-name>"; return 1; }

  local lang_file="${VIMX_LANGS_DIR}/${lang}.vim"
  local ftdetect_file="${VIMX_ROOT}/ftdetect/${lang}.vim"
  local syntax_file="${VIMX_ROOT}/syntax/${lang}.vim"

  echo -e "${CYAN}==========================================================${NC}"
  echo -e "${WHITE}Scaffold Language: ${CYAN}${lang}${NC}"
  echo -e "${CYAN}==========================================================${NC}"
  echo ""

  # Check what already exists
  local existing=0
  [ -f "$lang_file" ] && { echo -e "  ${YELLOW}⚠${NC} langs/${lang}.vim already exists"; existing=$((existing+1)); }
  [ -f "$ftdetect_file" ] && { echo -e "  ${YELLOW}⚠${NC} ftdetect/${lang}.vim already exists"; existing=$((existing+1)); }
  [ -f "$syntax_file" ] && { echo -e "  ${YELLOW}⚠${NC} syntax/${lang}.vim already exists"; existing=$((existing+1)); }

  if [ $existing -gt 0 ]; then
    echo ""
    read -p "$(echo -e "${CYAN}Overwrite existing files? [y/N]: ${NC}")" confirm
    [[ "$confirm" =~ ^[Yy]$ ]] || { echo -e "${BLUE}ℹ${NC} Cancelled"; return 0; }
  fi

  echo ""

  # Ask for file extensions
  read -p "$(echo -e "${CYAN}File extensions (comma-separated, e.g. rs,toml): ${NC}")" extensions
  extensions="${extensions:-$lang}"

  # Ask for comment style
  echo ""
  echo -e "  ${WHITE}Comment style:${NC}"
  echo -e "  ${GREEN}1.${NC} // (C-style)"
  echo -e "  ${GREEN}2.${NC} # (Shell/Python-style)"
  echo -e "  ${GREEN}3.${NC} -- (Lua/Haskell-style)"
  echo -e "  ${GREEN}4.${NC} ; (Lisp-style)"
  echo ""
  read -p "$(echo -e "${CYAN}Select [1-4, default=1]: ${NC}")" comment_style
  comment_style="${comment_style:-1}"

  local comment_char=""
  case "$comment_style" in
    1) comment_char="//" ;;
    2) comment_char="#" ;;
    3) comment_char="--" ;;
    4) comment_char=";" ;;
    *) comment_char="//" ;;
  esac

  # Create langs/<name>.vim
  echo ""
  echo -e "${BLUE}ℹ${NC} Creating langs/${lang}.vim..."
  cat > "$lang_file" << EOF
" ---------------------------
" ${lang} Development
" ---------------------------

" ${lang} specific settings
autocmd FileType ${lang} setlocal shiftwidth=2 tabstop=2
autocmd FileType ${lang} setlocal commentstring=${comment_char}\\ %s

" Key mappings
" autocmd FileType ${lang} nnoremap <buffer> <leader>r :!${lang} %<CR>

" Add your custom configuration below
EOF
  echo -e "  ${GREEN}✓${NC} Created ${CYAN}langs/${lang}.vim${NC}"

  # Create ftdetect/<name>.vim
  echo -e "${BLUE}ℹ${NC} Creating ftdetect/${lang}.vim..."
  IFS=',' read -ra EXT_ARRAY <<< "$extensions"
  {
    echo "\" Filetype detection for ${lang}"
    echo "\" Generated by vimx lang scaffold ${lang}"
    echo ""
    for ext in "${EXT_ARRAY[@]}"; do
      ext=$(echo "$ext" | xargs)  # trim whitespace
      echo "autocmd BufRead,BufNewFile *.${ext} set filetype=${lang}"
    done
  } > "$ftdetect_file"
  echo -e "  ${GREEN}✓${NC} Created ${CYAN}ftdetect/${lang}.vim${NC}"

  # Create syntax/<name>.vim
  echo -e "${BLUE}ℹ${NC} Creating syntax/${lang}.vim..."
  cat > "$syntax_file" << EOF
" Syntax highlighting for ${lang}
" Generated by vimx lang scaffold ${lang}
"
" For full syntax support, consider installing a plugin:
"   vimx add <user>/vim-${lang}

if exists("b:current_syntax")
  finish
endif

" Keywords
syn keyword ${lang}Keyword if then else endif while do done for in function return
syn keyword ${lang}Keyword class struct enum interface typedef import export

" Comments
syn match ${lang}Comment "${comment_char}.*$"
syn region ${lang}Comment start="/\*" end="\*/" contains=Todo

" Strings
syn region ${lang}String start='"' end='"' contains=Escape
syn region ${lang}String start="'" end="'" contains=Escape
syn match ${lang}Escape contained /\\\\./

" Numbers
syn match ${lang}Number "\<\d\+\>"
syn match ${lang}Number "\<0[xX][0-9a-fA-F]\+\>"

" Highlighting
hi def link ${lang}Keyword    Keyword
hi def link ${lang}Comment    Comment
hi def link ${lang}String     String
hi def link ${lang}Escape     Special
hi def link ${lang}Number     Number

let b:current_syntax = "${lang}"
EOF
  echo -e "  ${GREEN}✓${NC} Created ${CYAN}syntax/${lang}.vim${NC}"

  # Add to init.vim
  if ! grep -q "runtime! langs/${lang}.vim" "$VIMX_INIT"; then
    echo -e "${BLUE}ℹ${NC} Adding to init.vim..."
    add_language "$lang" 2>/dev/null
    echo -e "  ${GREEN}✓${NC} Added ${CYAN}runtime! langs/${lang}.vim${NC} to init.vim"
  fi

  echo ""
  echo -e "${GREEN}✓${NC} Scaffold complete! Files created:"
  echo -e "  ${CYAN}langs/${lang}.vim${NC}       — Language settings & keymaps"
  echo -e "  ${CYAN}ftdetect/${lang}.vim${NC}   — Filetype detection"
  echo -e "  ${CYAN}syntax/${lang}.vim${NC}    — Syntax highlighting"
  echo ""
  echo -e "  Edit: ${CYAN}vimx lang edit ${lang}${NC}"
  echo -e "  Next: ${CYAN}Install LSP with :CocInstall coc-${lang}${NC}"
}
